function inferEventType(title="",description="") { const text=`${title} ${description}`.toLowerCase(); if(/면접|interview|채용/.test(text)) return {type:"interview",confidence:.84,source:"local"}; if(/기사|toeic|토익|시험|exam|자격/.test(text)) return {type:"exam",confidence:.86,source:"local"}; if(/창업|startup|demo day|데모데이/.test(text)) return {type:"startup",confidence:.72,source:"local"}; return {type:"general",confidence:.55,source:"local",fallbackReason:"규칙에 맞는 키워드가 없어 일반 일정으로 분류했습니다."}; }
function classifyEvent(title,description="",adapter) { const allowed=new Set(["interview","exam","startup","general"]); if(adapter&&typeof adapter.classify==="function") try { const result=adapter.classify({title:String(title),description:String(description)}); if(!result||!allowed.has(result.type)||!Number.isFinite(Number(result.confidence))||Number(result.confidence)<0||Number(result.confidence)>1) throw new Error("AI 분류 응답 형식이 올바르지 않습니다."); return {type:result.type,confidence:Number(result.confidence),source:"ai"}; } catch(error) { return {...inferEventType(title,description),fallback:true,fallbackReason:`AI 분류 실패 — 로컬 안전 분류 사용 (${error?.message||"오류"})`}; } return inferEventType(title,description); }
function normalizePolicy(policy) { const known=SEED_POLICIES.find(item=>item.id===policy?.id)||{}; const sourceUrl=safeUrl(policy?.sourceUrl), applicationUrl=safeUrl(policy?.applicationUrl||policy?.officialUrl), checkedAt=String(policy?.checkedAt||"").trim(), status=sourceUrl&&checkedAt&&POLICY_STATES.includes(policy?.status)?policy.status:"unknown"; return {...clone(known),...clone(policy||{}),status,sourceUrl,applicationUrl,officialUrl:applicationUrl,checkedAt:checkedAt||"확인 시각 없음",isDemo:true,requirements:Array.isArray(policy?.requirements)?policy.requirements.filter(item=>typeof item==="string").slice(0,20):clone(known.requirements||[]),evidence:Array.isArray(policy?.evidence)?policy.evidence.filter(item=>typeof item==="string").slice(0,20):clone(known.evidence||[])}; }
function matchPolicy(policy,event,profile=PROFILE){if(!policy||!event)return null;const title=String(event.title||"");if(policy.id==="hanam-basic-income"){if(event.type!=="general"||(!title.includes("청년기본소득")&&event.id!=="event-basic-income"))return null;if(!String(profile.residence||"").includes("하남"))return {eligibility:"low",reason:"하남시 주민등록 조건을 충족하지 않습니다."};return {eligibility:"medium",reason:"2001년생·하남시 가상 프로필과 연결했지만 정확한 생년월일·거주기간 심사가 필요합니다."};}if(policy.id==="youth-hope-savings"){if(event.type!=="general"||!title.includes("희망적금"))return null;return {eligibility:"medium",reason:"2001년생 금융 관심 후보지만 신규 가입 가능 여부와 기존 가입·만기 상태를 확인해야 합니다."};}if(policy.id==="future-tomorrow-experience"){if(event.type!=="general"||!title.includes("일경험"))return null;return {eligibility:profile.status==="미취업"?"medium":"low",reason:"대학교 4학년·취업 준비·미취업 프로필과 일경험 공고를 연결했지만 공고별 선발 조건을 확인해야 합니다."};}if(policy.id==="interview-allowance"||policy.id==="exam-support"){if((policy.id==="interview-allowance"&&event.type!=="interview")||(policy.id==="exam-support"&&event.type!=="exam"))return null;if(!String(profile.residence||"").includes("경기도"))return {eligibility:"low",reason:"경기도 거주 조건을 충족하지 않습니다."};if(policy.id==="interview-allowance"&&profile.status!=="미취업")return {eligibility:"medium",reason:"재직 여부를 운영기관 기준으로 추가 확인해야 합니다."};return {eligibility:"high",reason:policy.id==="interview-allowance"?"경기도 거주·미취업 프로필과 면접 일정이 핵심 조건에 부합합니다.":"경기도 거주 프로필과 자격시험 일정이 연결됩니다."};}return null;}
function matchPolicies(event,policies=SEED_POLICIES,profile=PROFILE) { return policies.filter(policy=>POLICY_IDS.includes(policy.id)).map(policy=>{const result=matchPolicy(policy,event,profile); return result?{policy:normalizePolicy(policy),...result}:null;}).filter(Boolean); }
function buildTasks(event,matches=[],base=today) { if(!event) return []; const eventDate=new Date(`${event.date}T09:00:00+09:00`); const add=(offset,kind,title,body,extra={})=>{const due=new Date(eventDate); due.setDate(due.getDate()+offset); return {id:`${event.id}:${kind}:${isoDate(due)}`,eventId:event.id,kind,title,due:isoDate(due),body,completed:false,...extra};}; let tasks=[]; if(event.type==="interview") tasks=[add(-3,"before-3","채용공고·면접 안내 저장","면접 안내 이메일과 채용공고를 원본 그대로 보관합니다."),add(1,"after-1","면접확인서 요청","면접 다음 날 확인서 요청 초안을 보내고 회신을 기록합니다."),add(3,"after-3","확인서 미회신 후속","회신이 없으면 대체 증빙과 공식 안내 경로를 확인합니다.")]; else if(event.type==="exam") tasks=[add(-3,"receipt","결제영수증·접수확인 보관","결제 영수증과 접수 확인을 함께 보관합니다."),add(0,"attendance","응시 사실 보존","수험표나 응시 확인 화면을 남깁니다."),add(1,"employment-status","응시일 취업 상태 기록","신청 시 요구될 수 있는 취업 상태를 확인합니다.")]; for(const {policy} of matches){const p=normalizePolicy(policy); if(validDate(p.applicationStart)) tasks.push(add(diffDays(p.applicationStart,eventDate),`policy-start-${p.id}`,"접수 시작",`${p.title} 공식 접수 시작일을 확인합니다.`,{policyId:p.id,provenance:{sourceUrl:p.sourceUrl,checkedAt:p.checkedAt}})); if(validDate(p.applicationDeadline)) tasks.push(add(diffDays(p.applicationDeadline,eventDate),`policy-deadline-${p.id}`,"마감 임박",`${p.title} 신청 마감일과 제출 조건을 확인합니다.`,{policyId:p.id,provenance:{sourceUrl:p.sourceUrl,checkedAt:p.checkedAt}})); } return tasks.map(task=>{const days=diffDays(task.due,base); return {...task,overdue:days<0,state:days<0?"overdue":days<=3?"urgent":"soon"};}); }

function parseICSDate(raw,params={}) { const value=String(raw||"").trim(); if(/^\d{8}$/.test(value)){const date=`${value.slice(0,4)}-${value.slice(4,6)}-${value.slice(6,8)}`; if(!validDate(date)) throw new Error("ICS 날짜가 올바르지 않습니다."); return {date,timezoneWarning:false};} if(/^\d{8}T\d{6}Z$/.test(value)){const date=`${value.slice(0,4)}-${value.slice(4,6)}-${value.slice(6,8)}`; if(!validDate(date)) throw new Error("ICS 날짜가 올바르지 않습니다."); return {date,timezoneWarning:false};} if(/^\d{8}T\d{6}$/.test(value)){const date=`${value.slice(0,4)}-${value.slice(4,6)}-${value.slice(6,8)}`; if(!validDate(date)) throw new Error("ICS 날짜가 올바르지 않습니다."); const tz=String(params.TZID||""); const supported=new Set(["Asia/Seoul","Asia/Tokyo","UTC","Etc/UTC"]); return {date,timezoneWarning:!tz||!supported.has(tz)};} throw new Error("ICS DTSTART는 YYYYMMDD 또는 YYYYMMDDTHHMMSS 형식이어야 합니다."); }
