function loadAISettings(){try{return JSON.parse(sessionStorage.getItem(AI_SETTINGS_KEY)||"null")||{};}catch(_){return {};}}
function updateAISettingsForm(){const config=loadAISettings(),status=document.getElementById("ai-connection-status");["provider","model","endpoint"].forEach(key=>{const field=document.getElementById(`ai-${key}`);if(field&&config[key])field.value=config[key];});if(status){status.textContent=config.endpoint?"프록시 준비됨":"미연결";status.className=`badge ${config.endpoint?"cool":"neutral"}`;}}
function requestAIClassification(event,config=loadAISettings()){if(!config.endpoint||!config.endpoint.startsWith("/"))throw new Error("AI 프록시는 동일 출처의 /api 경로만 허용합니다.");return fetch(config.endpoint,{method:"POST",headers:{"content-type":"application/json",...(config.apiKey?{"x-calenfit-api-key":config.apiKey}:{})},body:JSON.stringify({model:config.model||undefined,input:{title:event.title,description:event.description,startTime:event.startTime||`${event.date}T09:00:00+09:00`},task:"classify_calendar_event",allowedTypes:["interview","exam","startup","general"]})}).then(async response=>{if(!response.ok)throw new Error(`AI 프록시 응답 ${response.status}`);const result=await response.json();if(!["interview","exam","startup","general"].includes(result?.type)||!Number.isFinite(Number(result?.confidence)))throw new Error("AI 응답 형식이 올바르지 않습니다.");return {type:result.type,confidence:Number(result.confidence),source:"ai"};});}
if(typeof document!=="undefined"&&typeof window!=="undefined"){
  document.addEventListener("click",event=>{
    if(event.target?.id==="landing-start-button"||event.target?.id==="landing-demo-button"){
      document.getElementById("landing-screen")?.classList.add("is-hidden");
      document.getElementById("main-content")?.focus?.();
      return;
    }
    if(event.target?.id==="expand-calendar"){
      const expanded=document.body.classList.toggle("calendar-focus-mode"),button=event.target;
      button.setAttribute("aria-expanded",String(expanded));
      button.textContent=expanded?"대시보드로 돌아가기":"전체 달력 보기";
      document.getElementById("calendar-panel")?.scrollIntoView({behavior:"smooth",block:"start"});
      announce(expanded?"전체 달력 보기로 전환했습니다.":"대시보드 보기로 돌아왔습니다.");
      return;
    }
    if(event.target?.id!=="reset-demo") return;
    const api=globalThis.calenfit;if(!api)return;
    const fresh=resetState();fresh.auth=api.state.auth;for(const key of Object.keys(api.state))delete api.state[key];Object.assign(api.state,fresh);clearVisibleErrors();api.state.notice="데모 데이터를 초기화했습니다.";api.render();
  });
  document.addEventListener("change",event=>{
    if(!event.target?.matches?.("[data-primary-proof]")) return;
    const api=globalThis.calenfit;if(!api)return;
    const selected=api.state.events.find(item=>item.id===api.state.selectedEventId);
    if(selected){selected.recovery=selected.recovery||{hasPrimary:false,alternatives:[]};selected.recovery.hasPrimary=event.target.value==="yes";saveState(api.state);api.render();announce(selected.recovery.hasPrimary?"면접확인서를 핵심 증빙으로 표시했습니다.":"면접확인서 없음으로 표시했습니다.");}
  });
  document.addEventListener("submit",event=>{
    if(event.target?.id!=="ai-settings-form")return;
    event.preventDefault();const data=new FormData(event.target),config={provider:String(data.get("provider")||""),model:String(data.get("model")||"").trim(),endpoint:String(data.get("endpoint")||"").trim(),apiKey:String(data.get("apiKey")||"")};
    try{if(config.endpoint&&!/^https:\/\/|^\//.test(config.endpoint))throw new Error("프록시 URL은 https URL 또는 /api 경로여야 합니다.");sessionStorage.setItem(AI_SETTINGS_KEY,JSON.stringify(config));updateAISettingsForm();announce(config.endpoint?"AI 프록시 설정을 이 탭에만 저장했습니다.":"AI 연결 설정을 비웠습니다.");}catch(error){announce(error.message,true);}
  });
  document.addEventListener("submit",event=>{
    const form=event.target?.closest?.("[data-edit-form]"),api=globalThis.calenfit;if(!form||!api)return;
    event.preventDefault();event.stopImmediatePropagation();const data=new FormData(form);
    try{updateEvent(api.state,form.dataset.editForm,{title:data.get("title"),date:data.get("date"),description:data.get("description"),type:data.get("type")});api.state.notice="일정을 수정했습니다.";api.render();}catch(error){api.state.error=error.message;api.render();}
  });
  document.addEventListener("keydown",event=>{
    if(event.key!=="Escape"||!document.body.classList.contains("calendar-focus-mode"))return;
    document.getElementById("expand-calendar")?.click();
  });
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",()=>{bootstrap();updateAISettingsForm();});else {bootstrap();updateAISettingsForm();}
}
if(typeof module!=="undefined")module.exports={STORAGE_KEY,SCHEMA_VERSION,PROFILE,SEED_POLICIES,SEED_EVENTS,RECOVERY_OPTIONS,MAX_EVIDENCE_BYTES,inferEventType,classifyEvent,normalizePolicy,parseICS,parseICSWithWarnings,matchPolicy,matchPolicies,buildTasks,evaluateRecovery,seedState,validateState,loadState,saveState,resetState,setTaskCompletion,createEvent,updateEvent,deleteEvent,addEvidence,extractEvidenceHints,formatDate,diffDays,policyStatusLabel,statusLabel,eventTypeLabel,validDate,safeUrl};

function renderConnectedProviders(state){const root=document.getElementById("calendar-connections");if(!root)return;root.innerHTML=calendarConnectionSummary(state).map(item=>`<article class="connection-item"><div><strong>${escapeHTML(item.name)}</strong><span class="form-help">${escapeHTML(item.id==="google"?"OAuth·webhook 서버 연동":item.id==="ics"?"브라우저 파일 미리보기":"localStorage 데모")}</span></div><span class="badge ${item.state==="synced"?"cool":item.state==="not-configured"?"neutral":"warm"}">${escapeHTML(item.label)}</span>${item.id==="google"?`<div class="connection-actions"><button type="button" class="secondary-button" data-google-connect>Google 연결 시작</button><button type="button" class="ghost-button" data-google-outcome="success">성공 mock</button><button type="button" class="ghost-button" data-google-outcome="denied">권한 거부 mock</button></div>`:""}</article>`).join("");}
function renderNotificationOutbox(state){const root=document.getElementById("notification-outbox");if(!root)return;root.innerHTML=state.notifications?.length?state.notifications.slice().reverse().map(item=>`<article class="outbox-item"><div><strong>${escapeHTML(item.payload.title)}</strong><span>${escapeHTML(item.channel)} · ${escapeHTML(item.payload.label)} · ${escapeHTML(item.payload.phone||"수신자 미표시")}</span></div><span class="badge ${item.status==="scheduled"?"cool":"warm"}">${escapeHTML(item.status==="scheduled"?"예약됨":item.reason||"차단됨")}</span><details><summary>payload 보기</summary><pre>${escapeHTML(JSON.stringify(item.payload,null,2))}</pre></details></article>`).join(""):"<p class=\"empty-state\">아직 예약된 알림이 없습니다. 수신 동의와 채널 상태를 확인하세요.</p>";}
function policyCtaMarkup(policy,source){if(!source)return "<button class=\"button-link\" type=\"button\" disabled>출처 확인 필요</button>";if(policy.status==="open")return "<a class=\"button-link\" href=\""+escapeHTML(source)+"\" target=\"_blank\">공식 신청 페이지 · 공식 공고 확인</a>";if(policy.status==="unknown")return "<a class=\"button-link\" href=\""+escapeHTML(source)+"\" target=\"_blank\">공식 공고 확인</a>";return "<button class=\"button-link\" type=\"button\" disabled>"+escapeHTML(policyStatusLabel(policy.status))+" — 신청 불가</button>";}
function renderAllPolicyCandidates(state){const root=document.getElementById("policy-cards");if(!root)return;const candidates=[];for(const event of state.events){for(const match of matchPolicies(event,state.policies,state.profile)){if(!candidates.some(item=>item.policy.id===match.policy.id))candidates.push({...match,event});}}root.innerHTML=candidates.length?candidates.map(({policy,eligibility,reason,event})=>"<article class=\"policy-card compact-policy\"><h3 class=\"policy-title\">"+escapeHTML(policy.title)+"</h3><span class=\"policy-amount\">"+escapeHTML(policy.amount)+"</span><span class=\"badge "+eligibility+"\">"+escapeHTML(statusLabel(eligibility))+"</span><p class=\"policy-summary\">"+escapeHTML(reason)+"</p><p class=\"policy-summary\">연결 일정: "+escapeHTML(event.title)+" · 상태: "+escapeHTML(policyStatusLabel(policy.status))+"</p><div class=\"cta-row\">"+policyCtaMarkup(policy,safeUrl(policy.sourceUrl))+"</div></article>").join(""):"<p class=\"empty-state\">현재 일정과 연결된 정책 후보가 없습니다.</p>";}
function refreshConnectedUI(){const api=globalThis.calenfit;if(!api)return;const main=document.getElementById("main-content");main?.classList.toggle("auth-anonymous",api.state.auth?.isLoggedIn!==true);main?.classList.toggle("authenticated",api.state.auth?.isLoggedIn===true);refreshProfilePanel(api.state);renderConnectedProviders(api.state);renderNotificationOutbox(api.state);renderMonthCalendar(api.state);renderAllPolicyCandidates(api.state);}
async function startGoogleOAuth(){const api=globalThis.calenfit;if(!api)return;const state=api.state;state.calendarConnections.google={state:"pending",label:"OAuth 연결 요청 중",demo:false};refreshConnectedUI();announce("Google OAuth 서버 연결을 요청하고 있습니다.");try{const response=await fetch("/api/calendar/google/connect",{headers:{accept:"application/json"}});if(!response.ok)throw new Error(`서버 설정 필요 (${response.status})`);const result=await response.json();const authUrl=new URL(String(result.authorizationUrl||result.authUrl||""),window.location.origin);if(authUrl.protocol!=="https:"||authUrl.hostname!=="accounts.google.com")throw new Error("안전한 Google OAuth URL이 아닙니다.");window.location.assign(authUrl.href);}catch(error){state.calendarConnections.google={state:"not-configured",label:"서버 설정 필요",demo:false,reason:error.message};saveState(state);refreshConnectedUI();announce(`Google Calendar를 연결할 수 없습니다. ${error.message} OAuth callback 서버를 설정하세요.`,true);}}
if(typeof document!=="undefined")document.addEventListener("click",event=>{if(event.target.closest?.("[data-google-connect]")){event.preventDefault();startGoogleOAuth();}});
if(typeof document!=="undefined"){
  const setupConnectedUI=()=>{refreshConnectedUI();const eventRoot=document.getElementById("event-list");if(eventRoot&&globalThis.MutationObserver){new MutationObserver(refreshConnectedUI).observe(eventRoot,{childList:true});}document.addEventListener("click",event=>{const api=globalThis.calenfit;if(!api)return;const connect=event.target.closest?.("[data-google-connect]"),outcome=event.target.closest?.("[data-google-outcome]");if(connect){api.state.calendarConnections.google=GoogleCalendarAdapter.connect({oauthConfigured:false});api.state.calendarConnections.google.label="서버 설정 필요";saveState(api.state);refreshConnectedUI();announce("Google OAuth 서버 설정이 필요합니다. 브라우저에서 토큰을 보관하지 않습니다.",true);return;}if(outcome){const result=GoogleCalendarAdapter.sync(outcome.dataset.googleOutcome);api.state.calendarConnections.google=result;saveState(api.state);refreshConnectedUI();announce(`${result.label} 상태를 표시했습니다.`);}});document.getElementById("notification-form")?.addEventListener("submit",event=>{event.preventDefault();const api=globalThis.calenfit;if(!api)return;const result=scheduleNotification(api.state,{eventId:api.state.selectedEventId,channel:document.getElementById("notification-channel")?.value,offset:Number(document.getElementById("notification-offset")?.value),consent:Boolean(document.getElementById("notification-consent")?.checked)});refreshConnectedUI();announce(result.status==="scheduled"?"웹 알림을 데모 아웃박스에 예약했습니다.":result.reason,true);});};if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",setupConnectedUI);else setupConnectedUI();}
