function refreshProfilePanel(state){const root=document.getElementById("profile-summary");if(root)root.innerHTML=`<div class="profile-item"><span class="meta-label">출생</span><span class="meta-value">${state.profile.birthYear}년생</span></div><div class="profile-item"><span class="meta-label">거주</span><span class="meta-value">${escapeHTML(state.profile.residence)}</span></div><div class="profile-item"><span class="meta-label">상태</span><span class="meta-value">${escapeHTML(state.profile.status)}</span></div><div class="profile-item"><span class="meta-label">학력</span><span class="meta-value">${escapeHTML(state.profileMeta?.education||state.profile.education||"미입력")}</span></div><div class="profile-item"><span class="meta-label">목표</span><span class="meta-value">${escapeHTML(state.profileMeta?.goal||state.profile.goal||"미입력")}</span></div>`;const badge=document.getElementById("profile-login-state");if(badge)badge.textContent=state.auth?.isLoggedIn?"데모 로그인됨":"로그인 없음";}
