if(typeof document!=="undefined")document.addEventListener("submit",async event=>{if(event.target.id!=="account-auth-form")return;event.preventDefault();const api=globalThis.calenfit;if(!api)return;const data=new FormData(event.target),action=event.submitter?.dataset.authAction||"login";try{const response=await fetch(`/api/auth/${action}`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({email:String(data.get("email")||""),password:String(data.get("password")||""),profile:api.state.profile})});const result=await response.json();if(!response.ok)throw new Error(result.error||"인증에 실패했습니다.");api.state.auth={isLoggedIn:true,mode:"account",userId:result.user?.id||null};api.state.profile={...api.state.profile,...result.user?.profile};saveState(api.state);api.render();refreshConnectedUI();document.querySelector("#account-auth")?.removeAttribute("open");document.querySelector(".profile-sidebar")?.classList.remove("is-editing");announce(action==="signup"?"계정을 만들고 로그인했습니다.":"로그인했습니다.");}catch(error){announce(`로그인 서버에 연결할 수 없습니다. ${error.message}`,true);}});
async function hydrateServerState(){if(window.location.port!=="8000")return;const api=globalThis.calenfit;if(!api)return;try{const session=await fetch("/api/auth/session");if(session.ok){const result=await session.json();api.state.auth={isLoggedIn:true,mode:result.user?.mode||"account",userId:result.user?.id||null};api.state.profile={...api.state.profile,...result.user?.profile};saveState(api.state);const eventsResponse=await fetch("/api/events");if(eventsResponse.ok){const eventData=await eventsResponse.json();api.state.events=Array.isArray(eventData.events)?eventData.events:[];api.state.selectedEventId=api.state.events[0]?.id||null;}api.render();}else{api.state.auth={isLoggedIn:false,mode:"anonymous"};try{localStorage.removeItem(STORAGE_KEY);}catch{}}const status=await fetch("/api/calendar/status");if(status.ok){const result=await status.json();api.state.calendarConnections.google={state:result.state,label:result.state==="synced"?"Google 동기화됨":"Google 서버 준비됨"};if(result.state==="synced"){const sync=await fetch("/api/calendar/google/sync");if(sync.ok){const data=await sync.json();for(const item of data.events||[]){const date=String(item.startTime||"").slice(0,10);if(!date||api.state.events.some(event=>event.providerId===item.providerId))continue;const inferred=inferEventType(item.title,item.description);api.state.events.push({id:`google-${item.providerId}`,providerId:item.providerId,title:item.title,description:item.description,date,type:inferred.type,confidence:inferred.confidence,classificationSource:"local",channel:"google",recovery:{hasPrimary:false,alternatives:[]}});}saveState(api.state);}}}refreshConnectedUI();}catch(_){/* local demo remains available */}}
if(typeof document!=="undefined"){const loadServer=()=>hydrateServerState();if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",loadServer);else loadServer();}
if(typeof document!=="undefined")document.addEventListener("click",async event=>{const button=event.target.closest?.("#login-button"),api=globalThis.calenfit;if(button&&api){try{const response=await fetch("/api/auth/demo",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({profile:api.state.profile})});if(response.ok){const result=await response.json();api.state.auth={isLoggedIn:true,mode:"server-demo",userId:result.user?.id||null};saveState(api.state);refreshConnectedUI();announce("서버 세션으로 데모 로그인했습니다.");}}catch(_){/* static demo fallback remains active */}return;}if(event.target.closest?.("#run-ai-analysis")&&api){const selected=api.state.events.find(item=>item.id===api.state.selectedEventId)||api.state.events[0];try{const result=await requestAIClassification(selected);Object.assign(selected,{type:result.type==="general"&&inferEventType(selected.title,selected.description).type!=="general"?inferEventType(selected.title,selected.description).type:result.type,confidence:result.confidence,classificationSource:"ai"});saveState(api.state);api.render();refreshConnectedUI();announce("Grok 분석 결과를 반영해 정책 후보를 다시 계산했습니다.");}catch(error){announce(`Grok 연결 실패. 로컬 안전 분류를 유지합니다: ${error.message}`,true);}}});
